class NumMatrix { vector<vector<int>> prefix;public:NumMatrix(vector<vector<int>>& matrix):prefix(matrix.size()+1,vector<int>(matrix[0].size()+1)){for(int r=0;r<(int)matrix.size();++r)for(int c=0;c<(int)matrix[0].size();++c)prefix[r+1][c+1]=matrix[r][c]+prefix[r][c+1]+prefix[r+1][c]-prefix[r][c];}int sumRegion(int row1,int col1,int row2,int col2){return prefix[row2+1][col2+1]-prefix[row1][col2+1]-prefix[row2+1][col1]+prefix[row1][col1];} };
